// Контексты не должны знать друг о друге напрямую
// Коммуникация через Domain Events / Anti-Corruption Layer

// Order Context
namespace OrderContext {
  export interface Order {
    id: OrderId;
    customerId: CustomerId;
    items: OrderItem[];
    status: OrderStatus;
    total: Money;
  }

  export class OrderService {
    constructor(
      private orders: OrderRepository,
      private eventBus: EventBus
    ) {}

    async placeOrder(cmd: PlaceOrderCommand): Promise<OrderId> {
      const order = Order.create(cmd);
      await this.orders.save(order);
      await this.eventBus.publish(new OrderPlaced(order));
      return order.id;
    }
  }
}

